// 1. Extension of a standard control
Input.extend("my.app.control.UpperCaseInput", { /* ... */ });

// 2. Composite control: built from other controls
Control.extend("my.app.control.LabeledInput", {
  metadata: {
    aggregations: { _label: { type: "sap.m.Label", multiple: false, visibility: "hidden" } }
  }
  /* ... */
});

// 3. Completely new control with its own HTML
Control.extend("my.app.control.StatusBadge", { /* metadata + renderer */ });

sap.ui.define([
  "sap/ui/core/Control",
  "sap/m/Label",
  "sap/m/Input"
], function (Control, Label, Input) {
  "use strict";

  return Control.extend("my.app.control.LabeledInput", {
    metadata: {
      properties: {
        label: { type: "string", defaultValue: "" },
        value: { type: "string", defaultValue: "" }
      },
      aggregations: {
        _label: { type: "sap.m.Label", multiple: false, visibility: "hidden" },
        _input: { type: "sap.m.Input", multiple: false, visibility: "hidden" }
      },
      events: {
        change: { parameters: { value: { type: "string" } } }
      }
    },

    init: function () {
      const input = new Input({
        change: function (event) {
          const value = event.getParameter("value");
          this.setProperty("value", value, true);
          this.fireChange({ value: value });
        }.bind(this)
      });
      this.setAggregation("_input", input);
      this.setAggregation("_label", new Label({ labelFor: input }));
    },

    onBeforeRendering: function () {
      this.getAggregation("_label").setText(this.getLabel());
      this.getAggregation("_input").setValue(this.getValue());
    },

    renderer: {
      apiVersion: 2,
      render: function (rm, control) {
        rm.openStart("div", control);
        rm.class("myAppLabeledInput");
        rm.openEnd();
        rm.renderControl(control.getAggregation("_label"));
        rm.renderControl(control.getAggregation("_input"));
        rm.close("div");
      }
    }
  });
});

sap.ui.define([
  "sap/m/Input",
  "sap/m/InputRenderer"
], function (Input, InputRenderer) {
  "use strict";

  return Input.extend("my.app.control.UpperCaseInput", {
    metadata: {
      properties: {
        upperCase: { type: "boolean", defaultValue: true }
      }
    },

    setValue: function (value) {
      const newValue = this.getUpperCase() && value ? value.toUpperCase() : value;
      return Input.prototype.setValue.call(this, newValue);
    },

    renderer: InputRenderer // reuse the standard renderer unchanged
  });
});

Control.extend("my.app.control.TagList", {
  metadata: {
    properties: {
      title:   { type: "string", defaultValue: "" },
      maxTags: { type: "int", defaultValue: 10 },
      state:   { type: "sap.ui.core.ValueState", defaultValue: "None" }
    },
    defaultAggregation: "tags",
    aggregations: {
      tags: { type: "sap.m.Token", multiple: true, singularName: "tag" }
    },
    associations: {
      ariaLabelledBy: { type: "sap.ui.core.Control", multiple: true, singularName: "ariaLabelledBy" }
    },
    events: {
      tagPress: { parameters: { tag: { type: "sap.m.Token" } } }
    }
  }
  // generated: getTitle/setTitle, addTag/removeTag/getTags,
  //            addAriaLabelledBy, attachTagPress/fireTagPress, ...
});

renderer: {
  apiVersion: 2,
  render: function (rm, control) {
    rm.openStart("div", control);                 // root element with the control's ID
    rm.class("myAppStatusBadge");
    rm.class("myAppStatusBadge" + control.getStatus());
    rm.attr("tabindex", "0");
    rm.accessibilityState(control, { role: "button" });
    rm.openEnd();

    rm.openStart("span");
    rm.class("myAppStatusBadgeText");
    rm.openEnd();
    rm.text(control.getText());                    // escaped text
    rm.close("span");

    rm.close("div");
  }
}

sap.ui.define([
  "sap/m/Input"
], function (Input) {
  "use strict";

  return Input.extend("my.app.control.PrefixInput", {
    metadata: {
      properties: { prefix: { type: "string", defaultValue: "" } }
    },
    renderer: {
      // no render(): UI5 extends the Input renderer and replaces only this hook.
      // prependInnerContent is a protected, empty hook of sap.m.InputBaseRenderer
      // that writes content before the inner <input> element.
      prependInnerContent: function (rm, control) {
        rm.openStart("span");
        rm.class("myAppInputPrefix");
        rm.openEnd();
        rm.text(control.getPrefix());
        rm.close("span");
      }
    }
  });
});

